input.command:
cd "C:/Users/pssps/Documents/Projects/sc4sap_project"; mkdir -p .sc4sap/work/S4-DEV/biz-scenarios; node -e "
const b='.sc4sap/work/HKT-DEV/biz-scenarios/';const out={generated:'2026-11-10',source:'HKT-DEV candidates s4dev_deferred + triage next_step S4DEV',target:{profile:'S4-DEV',sapVersion:'S4',abapRelease:'816',client:'100'},
prerequisites:['switch active MCP profile to S4-DEV (sap-option) and fully restart Claude Code','install biz handler classes (S/4 variant of ZCL_MCP_BIZ_*, ZMCP_BIZ_EXECUTE, ZMCP_BIZ_LOG) in a user-approved package + TR on S4-DEV','check S/4 release API equivalents for deferred areas before writing scenarios','declare expected results first; register every config change in S4-DEV CONFIG-CHANGES-TO-REVERT.md'],areas:[],triage_items:[]};
for(const m of ['MM','PP','FI','CO','LE','WM']){const t=require('./'+b+m+'-candidates.json');for(const d of t.s4dev_deferred)out.areas.push({module:m,...d,status:'TO_DESIGN'})}
const tr=require('./'+b+'triage-2026-11-10.json');out.triage_items=tr.items.filter(x=>x.next_step==='S4DEV').map(x=>({id:x.id,module:x.module,why:x.why,status:'TO_RUN'}));
require('fs').writeFileSync('.sc4sap/work/S4-DEV/biz-scenarios/S4DEV-plan.json',JSON.stringify(out,null,2));console.log(out.areas.length,'areas',out.triage_items.length,'items')"

